"""Independent validation for the outputs generated by 01_prepare_2AM9.py."""

from __future__ import annotations

import json
from pathlib import Path

from prepare_utils import read_tes_from_pdb, validate_repaired_outputs


ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "data" / "prepared" / "2AM9"


def main() -> None:
    _, tes_coords = read_tes_from_pdb(ROOT / "data" / "PDB" / "2AM9.pdb")
    repair_info = json.loads((OUT / "repair_info.json").read_text())
    result = validate_repaired_outputs(
        OUT,
        OUT / "receptor_repair_input.pdb",
        OUT / "receptor_repaired.pdb",
        OUT / "receptor_repaired_H.pdb",
        OUT / "receptor_repaired.pdbqt",
        OUT / "TES.pdbqt",
        OUT / "vina_box.txt",
        tes_coords,
        repair_info,
    )
    (OUT / "validation_repaired.json").write_text(json.dumps(result, indent=2))
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

